// Generate independently portable gateways from the maintained adapter modules.
const root = new URL("../", import.meta.url);
const config = JSON.parse(await Deno.readTextFile(new URL("deno.json", root)));
const client = await Deno.readTextFile(new URL("src/gateway/client.ts", root));
for (const name of ["http", "stdio"]) {
  const adapter =
    (await Deno.readTextFile(new URL("src/gateway/" + name + ".ts", root)))
      .replace(/^import \{[^\n]+\} from "\.\/client\.ts";\r?\n/, "");
  let source =
    "// Generated by deno task build:gateways. Edit src/gateway instead.\n// deno-lint-ignore-file no-import-prefix\n" +
    client + "\n" + adapter;
  for (const [alias, specifier] of Object.entries(config.imports)) {
    source = source.replaceAll(
      JSON.stringify(alias),
      JSON.stringify(specifier),
    );
  }
  await Deno.writeTextFile(new URL(name + ".ts", root), source);
}
